import {createMechanicsProject} from '../../src/projectLifecycle.js';
import {createComponentResource,editComponentSource,publishComponentSource} from '../../src/componentResources.js';
import {addMechanicInstance} from '../../src/mechanicDescriptions.js';
import {reference} from '../../src/valueSchemas.js';
import {createWidget,createWidgetElement,rectTransform} from '../../src/widgetModel.js';
import {makeAction} from '../../src/model.js';
import {ensureGameplay} from '../../src/gameplayModel.js';
export const pixel='data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVQIHWP4z8DwHwAFgAI/ScLbtAAAAABJRU5ErkJggg==';
export function transferTarget(title,outputKey='result'){const p=createMechanicsProject(title),scene=p.subscenes[0];p.variables[outputKey]=0;p.variableTypes={[outputKey]:'number'};for(const [id,name,x]of [[title+'-a','Дверь склада',-2],[title+'-b','Дверь архива',2]])p.objects.push({id,name,type:'Меш',active:true,subsceneId:scene.id,primitive:'box',transforms:{[scene.id]:{position:[x,1,0],rotation:[0,0,0],scale:[1,2,.2]}}});ensureGameplay(p);return p;}
export function transferFixture(){
 const p=transferTarget('A'),helper=createComponentResource(p,{name:'Scale'});editComponentSource(p,helper.id,`const component={name:'Scale',parameters:{type:'object',properties:{factor:{type:'number',default:2}}},state:{type:'object',properties:{calls:{type:'number',default:0}}},methods:{scale:{name:'Умножить',parameters:{type:'object',properties:{n:{type:'number'}}},result:{type:'number'},run({args,params,state}){state.calls++;return args.n*params.factor;}},ready:{name:'Готов',result:{type:'boolean'},run(){return true;}}}};`);publishComponentSource(p,helper.id);const h=addMechanicInstance(p,helper.definitionId,{kind:'project',id:p.id});h.name='Помощник';
 const event={id:'receipt-event',name:'Отметить счёт',owner:'GameSession',retention:'AUTO_CLOSE_ON_FLOW_END',groups:[{id:'receipt-group',actions:[{...makeAction('gameplay'),command:'sacura.game.message',operationVersion:1,value:{message:'Счёт обновлён'},duration:0}]}]};p.events.push(event);
 const resource=createComponentResource(p,{name:'ParcelCounter'});editComponentSource(p,resource.id,`const component={name:'ParcelCounter',parameters:{type:'object',properties:{step:{type:'number',default:1}}},state:{type:'object',properties:{value:{type:'number',default:0},awards:{type:'number',default:0},notices:{type:'number',default:0}}},references:{type:'object',properties:{helper:{type:'reference',referenceType:'mechanic'},controls:{type:'reference',referenceType:'widget'}}},signals:{changed:{name:'Изменён',payloadSchema:{type:'object',properties:{value:{type:'number'}}}}},lifecycle:{initialize:'initialize'},subscriptions:[{id:'notice',signal:'victory',methodId:'notice',match:'any'}],methods:{notice:{name:'Сигнал получен',run({state}){state.notices++;}},initialize:{name:'Начальная награда',run({state}){state.awards++;}},add:{name:'Добавить',parameters:{type:'object',properties:{amount:{type:'number'}}},result:{type:'number'},async run({args,params,state,refs,engine,global}){const n=args.amount * params.step;state.value+=await engine.invoke(refs.helper,'scale',{n});global.result=state.value;await engine.emit('changed',{value:state.value});await engine.event('Отметить счёт',{join:'FLOW_END'});return state.value;}},wait:{name:'Ждать сигнал',async run({engine,state}){await engine.waitSignal('victory');state.value+=100;}}}};`);publishComponentSource(p,resource.id);
 const a=addMechanicInstance(p,resource.definitionId,{kind:'object',id:p.objects[0].id},{step:2}),b=addMechanicInstance(p,resource.definitionId,{kind:'object',id:p.objects[1].id},{step:5});a.name='Складской счётчик';b.name='Архивный счётчик';
 const widget=createWidget('transfer-hud','hud','Счётчики посылок');widget.elements=[];const layout=(x,y,width=250)=>rectTransform({anchorMin:[0,0],anchorMax:[0,0],pivot:[0,0],x,y,width,height:54});
 for(const [m,x]of [[a,30],[b,320]]){m.references={helper:reference('mechanic',h.id),controls:reference('widget',widget.id)};widget.elements.push(createWidgetElement('button-'+m.id,'button',{name:m.name,text:m.name,action:'gameplay',command:'sacura.component.call',operationVersion:1,value:{instance:reference('mechanic',m.id),methodId:'add',args:{amount:1}},layout:layout(x,100)}));}
 widget.elements.push(createWidgetElement('total','text',{name:'Результат',binding:{source:'variable',path:'result',format:'Результат: {value}'},layout:layout(30,25,540)}),createWidgetElement('image','image',{name:'Ресурс посылок',src:pixel,layout:layout(610,100,54)}));p.widgets.push(widget);p.gameplay.hudWidgetId=widget.id;
 const tree=createComponentResource(p,{name:'Подготовленное поведение',kind:'behavior.tree'});tree.root='ready';tree.nodes=[{id:'ready',kind:'task',componentMethod:{definitionId:helper.definitionId,definitionVersion:1,methodId:'ready'},call:{instance:reference('mechanic',h.id),methodId:'ready',args:{}}}];const behavior=addMechanicInstance(p,tree.definitionId,{kind:'project',id:p.id});
 return {p,resource,helper,tree,a,b,h,behavior,widget};
}
export function transferBindings(pkg,p){return Object.fromEntries(pkg.inputs.map(i=>[i.id,i.type==='variable'?(i.nativeReference?p.gameplay.variableBindings.find(v=>v.key===Object.keys(p.variables)[0]).id:Object.keys(p.variables)[0]):i.type==='object'?p.objects.find(o=>o.name===i.name)?.id:i.type==='scene'?p.subscenes[0].id:undefined]));}
